#include <utility>
#include <string>

std::pair<int, std::string> p1(42, "hello"); // C++11: прямое создание
auto p2 = std::make_pair(3.14, true);        // тип выводится автоматически
auto p3 = std::pair{10, "world"};            // CTAD (C++17)

// Доступ к элементам
p1.first;   // 42
p1.second;  // "hello"

// Structured bindings (C++17) — разбираем pair на переменные
auto [num, str] = p1; // num=42, str="hello"

// Сравнение — лексикографическое (сначала первый элемент, потом второй)
std::pair<int,int> a{1,2}, b{1,3};
std::cout << (a < b); // true — 1==1, потом 2<3

#include <map>
#include <string>

int main() {
    // Ключи уникальны, отсортированы по алфавиту
    std::map<std::string, int> ages;
    ages["Alice"] = 25;
    ages["Bob"] = 30;
    ages.emplace("Charlie", 35); // эффективнее для сложных типов

    // Доступ к значению по ключу
    ages["Alice"];     // 25 — ВНИМАНИЕ: создаёт запись со значением по умолчанию, если ключа нет!
    ages.at("Alice");  // 25 — бросает исключение out_of_range, если ключа нет (безопаснее)

    // Поиск без создания записи
    auto it = ages.find("Bob");
    if (it != ages.end()) {
        std::cout << it->first << ": " << it->second; // "Bob: 30"
    }

    // Проверка наличия (C++20)
    if (ages.contains("Alice")) { ... } // true

    // Перебор — элементы идут в отсортированном порядке по ключу
    for (const auto& [name, age] : ages) {
        std::cout << name << " -> " << age << '\n';
    }

    // Удаление
    ages.erase("Bob");
    ages.clear();
}

#include <set>
#include <string>

std::set<int> s = {3, 1, 4, 1, 5}; // {1, 3, 4, 5} — дубликат 1 удалён, отсортировано
s.insert(2);    // {1, 2, 3, 4, 5}
s.erase(3);     // {1, 2, 4, 5}
s.count(4);     // 1 — элемент есть
s.count(99);    // 0 — элемента нет
s.contains(4);  // C++20: true

// Перебор в отсортированном порядке
for (int x : s) std::cout << x << ' '; // 1 2 4 5

#include <unordered_map>
#include <string>

std::unordered_map<std::string, int> umap;
umap["key"] = 42;
// Не упорядочены, быстрее для поиска, но нет итерации в сортированном порядке
// Требуют хеш-функцию и operator== для ключа

#include <stack>
#include <queue>

std::stack<int> st;       // LIFO
st.push(1); st.push(2); st.push(3);
st.top();   // 3
st.pop();   // убирает 3

std::queue<int> q;        // FIFO
q.push(1); q.push(2); q.push(3);
q.front();  // 1
q.pop();    // убирает 1

std::priority_queue<int> pq; // max-heap, большой элемент сверху
pq.push(5); pq.push(1); pq.push(10);
pq.top(); // 10

#include <algorithm>
#include <vector>

std::vector<int> v = {5, 2, 8, 1, 9};

std::sort(v.begin(), v.end());           // {1,2,5,8,9} — сортировка по возрастанию
std::reverse(v.begin(), v.end());        // {9,8,5,2,1} — переворот
auto it = std::find(v.begin(), v.end(), 5); // итератор на элемент 5
bool has = std::binary_search(v.begin(), v.end(), 5); // true (требует предварительной сортировки)
std::for_each(v.begin(), v.end(), [](int& x){ x *= 2; }); // удвоить каждый элемент
